/// <summary>
/// Base class for PricingAttribute table <c>SalesTable</c>
/// </summary>
public abstract class METGUPPricingAttributeSalesTable extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
    /// <summary>
    /// Returns the table record associated with pricing attribute group
    /// </summary>
    /// <param name = "_pricingObject">Attribute group object</param>
    /// <returns>Returns the table record associated with pricing attribute group</returns>
    protected SalesTable getTableRecord(Common _pricingObject)
    {
        SalesTable salesTable = _pricingObject as SalesTable;

        return salesTable;
    }

/// <summary>
/// Get data source identifier in query
/// </summary>
/// <returns>Get data source identifier in query</returns>
public str getQueryBuilderDatasourceIdentifier()
{
    return tableStr(SalesTable);
}

/// <summary>
/// Get tabel name for attribute group
/// </summary>
/// <returns>Get tabel name for attribute group</returns>
public TableName getTableName()
{
    return tableStr(SalesTable);
}

    /// <summary>
    /// Get the query build data source
    /// </summary>
    /// <param name = "_query">Query</param>
    /// <param name = "_qbdsMap">datasource map</param>
    /// <returns>Get the query build data source</returns>
    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(SalesTable)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(SalesTable));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(SalesTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(SalesTable), qbdsRoot);
            }
        }

        return qbdsRoot;
    }

    /// <summary>
    /// Get pricing attribute object query
    /// </summary>
    /// <param name = "_query">Main query</param>
    /// <param name = "_value">Value</param>
    /// <param name = "_qdbsMap">datasource map</param>
    /// <returns>Get pricing attribute object query</returns>
    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }

/// <summary>
/// Get path of the attribute field
/// </summary>
/// <returns>Get path of the attribute field</returns>
public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2',
        tableStr(SalesTable),
        this.getAttributeFieldIdentifier());
}

/// <summary>
/// Returns field number of the table field for attribute. Method is abstract and should be implemented in attribute field class
/// </summary>
/// <returns>Returns field number of the table field for attribute</returns>
public abstract FieldId getField()
{
}
